-- mercy-engine: every file on Meera's laptop as evidence, as
-- scripts/seed_laptop_files.py prints it -- the wedding set, the photographs
-- of the two of them, the phone screenshots (LAP-PHOTO-17..35) and her
-- personal papers (LAP-DOC-07..12) included. Applied to the single-player
-- schema, the event's template and any live participant.
--   docker compose exec -T mercy-engine-db sh -c 'psql -U "$POSTGRES_USER" -d "$POSTGRES_DB"' < services/mercy-engine/scripts/migrate_live_laptop_docs.sql
-- Idempotent: safe to run again.
DO $mig$ DECLARE sch TEXT; BEGIN
  FOR sch IN SELECT nspname FROM pg_namespace WHERE nspname IN ('public', 'template') OR nspname LIKE 'p\_%' LOOP
    EXECUTE format('SET LOCAL search_path TO %I', sch);
    IF to_regclass('evidence_cache') IS NOT NULL THEN
      EXECUTE $sql$
